#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);long long tot=0,t,v;for(i=0;i<n;i++)tot+=a[i];t=tot/2;static char dp2[100005];for(v=0;v<=t;v++)dp2[v]=0;dp2[0]=1;for(i=0;i<n;i++)for(v=t;v>=a[i];v--)if(dp2[v-a[i]])dp2[v]=1;long long best=0;for(v=t;v>=0;v--)if(dp2[v]){best=v;break;}printf("%lld\n",tot-2*best);return 0;}
